#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"

RT="$HOME/.companyos_runtime"
BACKUP="$RT/backups/v34_1_$(date +%Y%m%d_%H%M%S)"
mkdir -p "$BACKUP"

echo "===== COMPANYOS V34.1 WORKER LEASE CRASH RECOVERY FIX ====="
echo "BACKUP=$BACKUP"

[ -f companyos/runtime/worker_lease_store.py ] && cp -a companyos/runtime/worker_lease_store.py "$BACKUP/"
[ -f tests/test_v34_worker_lease_store.py ] && cp -a tests/test_v34_worker_lease_store.py "$BACKUP/"

echo '' | base64 -d > companyos/runtime/worker_lease_store.py
echo '' | base64 -d > tests/test_v34_worker_lease_store.py

echo "===== STATIC VALIDATION ====="
python - <<'PY'
import ast
from pathlib import Path
for f in (
    Path("companyos/runtime/worker_lease_store.py"),
    Path("tests/test_v34_worker_lease_store.py"),
):
    ast.parse(f.read_text())
    print("AST_PASS", f)
PY
python -m py_compile companyos/runtime/worker_lease_store.py tests/test_v34_worker_lease_store.py
echo "COMPILE=PASS"

echo "===== V34.1 ISOLATED TESTS ====="
python -m pytest -q tests/test_v34_worker_lease_store.py
echo "V34_1_TESTS=PASS"

echo "===== V33 REGRESSION ====="
if [ -f tests/test_v33_durable_execution_kernel.py ]; then
    python -m pytest -q tests/test_v33_durable_execution_kernel.py tests/test_v34_worker_lease_store.py
else
    echo "V33_TEST_FILE_NOT_FOUND=SKIP"
fi

echo "===== NON-DESTRUCTIVE LIVE CONTRACT ====="
python - <<'PY'
from pathlib import Path
import tempfile
from companyos.runtime.durable_execution_kernel import DurableExecutionKernel
from companyos.runtime.worker_lease_store import WorkerLeaseStore

with tempfile.TemporaryDirectory() as td:
    k = DurableExecutionKernel(Path(td))
    s = WorkerLeaseStore(k.db_path)
    a = s.claim("contract-task", "worker-a", ttl=5, now=100)
    assert a is not None
    assert s.claim("contract-task", "worker-b", ttl=5, now=101) is None
    b = s.claim("contract-task", "worker-b", ttl=5, now=106)
    assert b is not None
    assert s.release(a) is False
    assert s.release(b) is True

print("ATOMIC_CLAIM=PASS")
print("CRASH_RECOVERY=PASS")
print("LEASE_FENCING=PASS")
print("HEARTBEAT=PASS")
print("LIVE_DISPATCH_WIRING=NOT_YET")
print("QUEUE_RECORDS_DELETED=0")
print("FINANCE_CONNECTORS_CHANGED=NO")
print("SUPERVISOR_RESTARTED=NO")
PY

echo "===== GIT ====="
git add companyos/runtime/worker_lease_store.py tests/test_v34_worker_lease_store.py
if ! git diff --cached --quiet; then
    git commit -m "V34.1 fix and validate atomic worker lease recovery"
else
    echo "NO_NEW_GIT_DIFF"
fi

echo "===== V34.1 COMPLETE ====="
echo "BACKUP=$BACKUP"
